// src/components/Jugador/MisPagos.js
import React, { useState, useEffect } from 'react';
import { getPagos, getCurrentUser, getEntrenamientos, getPartidos } from '../../database/db';
import './MisPagos.css';

function MisPagos() {
  const [pagos, setPagos] = useState([]);
  const [entrenamientos, setEntrenamientos] = useState([]);
  const [partidos, setPartidos] = useState([]);
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    cargarDatos();
  }, []);

  const cargarDatos = async () => {
    setLoading(true);
    try {
      const currentUser = getCurrentUser();
      setUser(currentUser);
      
      const [pagosData, entrenamientosData, partidosData] = await Promise.all([
        getPagos(),
        getEntrenamientos(),
        getPartidos()
      ]);
      
      setPagos(pagosData || []);
      setEntrenamientos(entrenamientosData || []);
      setPartidos(partidosData || []);
    } catch (error) {
      console.error('Error cargando datos:', error);
      alert('Error al cargar los datos');
    }
    setLoading(false);
  };

  const getPagosJugador = () => {
    return pagos.filter(p => p.jugador_id === user?.id);
  };

  const getPagosPendientes = () => {
    return getPagosJugador().filter(p => p.estado === 'pendiente');
  };

  const getPagosRealizados = () => {
    return getPagosJugador().filter(p => p.estado === 'pagado');
  };

  const getDeudaTotal = () => {
    return getPagosPendientes().reduce((total, p) => total + (p.monto || 0), 0);
  };

  const getEventoNombre = (pago) => {
    if (pago.concepto === 'entrenamiento') {
      const ent = entrenamientos.find(e => e.id === pago.referencia_id);
      return ent ? `Entrenamiento - ${formatearFecha(ent.fecha)}` : 'Entrenamiento';
    } else if (pago.concepto === 'partido') {
      const part = partidos.find(p => p.id === pago.referencia_id);
      return part ? `Partido vs ${part.rival} - ${formatearFecha(part.fecha)}` : 'Partido';
    }
    return pago.concepto;
  };

  const formatearFecha = (fecha) => {
    if (!fecha) return 'Fecha no disponible';
    try {
      const fechaObj = new Date(fecha);
      if (!isNaN(fechaObj.getTime())) {
        return fechaObj.toLocaleDateString('es-ES', { day: 'numeric', month: 'long', year: 'numeric' });
      }
      return fecha;
    } catch (e) {
      return 'Fecha inválida';
    }
  };

  const pagosPendientes = getPagosPendientes();
  const pagosRealizados = getPagosRealizados();
  const deudaTotal = getDeudaTotal();

  if (loading) {
    return (
      <div className="mis-pagos">
        <div className="loading-container">
          <i className="fas fa-spinner fa-spin"></i>
          <p>Cargando tu información de pagos...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="mis-pagos">
      <div className="header-mis-pagos">
        <h2><i className="fas fa-dollar-sign"></i> Mis Pagos</h2>
        <p className="subtitle">Estado de cuenta y historial de pagos</p>
      </div>

      {/* Resumen de deuda */}
      <div className="resumen-deuda">
        <div className={`deuda-card ${deudaTotal > 0 ? 'pendiente' : 'pagado'}`}>
          <i className="fas fa-coins"></i>
          <div className="deuda-info">
            <span>Total pendiente</span>
            <strong>${deudaTotal.toLocaleString()}</strong>
          </div>
        </div>
        <div className="deuda-card">
          <i className="fas fa-check-circle"></i>
          <div className="deuda-info">
            <span>Pagos realizados</span>
            <strong>{pagosRealizados.length}</strong>
          </div>
        </div>
      </div>

      {/* Pagos pendientes */}
      <div className="seccion-pagos">
        <h3><i className="fas fa-clock"></i> Pagos Pendientes</h3>
        {pagosPendientes.length === 0 ? (
          <div className="no-pagos">
            <i className="fas fa-check-circle"></i>
            <p>¡No tienes pagos pendientes! Estás al día.</p>
          </div>
        ) : (
          <div className="pagos-lista">
            {pagosPendientes.map(pago => (
              <div key={pago.id} className="pago-item pendiente">
                <div className="pago-info">
                  <div className="pago-concepto">
                    <i className="fas fa-futbol"></i>
                    <span>{getEventoNombre(pago)}</span>
                  </div>
                  <div className="pago-monto">
                    <strong>${pago.monto}</strong>
                  </div>
                </div>
                <div className="pago-estado">
                  <span className="badge-pendiente">Pendiente de pago</span>
                </div>
              </div>
            ))}
            <div className="total-pendiente">
              <span>Total a pagar:</span>
              <strong>${deudaTotal.toLocaleString()}</strong>
            </div>
          </div>
        )}
      </div>

      {/* Historial de pagos */}
      {pagosRealizados.length > 0 && (
        <div className="seccion-pagos">
          <h3><i className="fas fa-history"></i> Historial de Pagos</h3>
          <div className="pagos-lista">
            {pagosRealizados.map(pago => (
              <div key={pago.id} className="pago-item pagado">
                <div className="pago-info">
                  <div className="pago-concepto">
                    <i className="fas fa-futbol"></i>
                    <span>{getEventoNombre(pago)}</span>
                  </div>
                  <div className="pago-monto">
                    <strong>${pago.monto}</strong>
                  </div>
                </div>
                <div className="pago-detalle">
                  <span className="pago-fecha">{pago.fecha_pago ? new Date(pago.fecha_pago).toLocaleDateString() : 'Fecha no disponible'}</span>
                  <span className="pago-metodo">{pago.metodo_pago === 'qr' ? '📱 QR' : '💵 Manual'}</span>
                </div>
                <div className="pago-estado">
                  <span className="badge-pagado">Pagado ✓</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

export default MisPagos;
